-- Promote the validated collections schema from staging names to production names.

alter type public.test_collection_item_type rename to collection_item_type;
alter type public.test_movie_watch_status rename to movie_watch_status;

alter table public.test_collection_items rename to collection_items;
alter table public.test_collection_movies rename to collection_movies;
alter table public.test_collection_inbox_links rename to collection_inbox_links;
alter table public.test_collection_purchases rename to collection_purchases;
alter table public.test_collection_birthdays rename to collection_birthdays;
alter table public.test_collection_places rename to collection_places;
alter table public.test_collection_learning rename to collection_learning;
alter table public.test_collection_calendar_events rename to collection_calendar_events;

alter function public.test_create_collection_movie(text,text,smallint,smallint,text[],text,text,text,text,text,public.movie_watch_status,numeric,integer) rename to create_collection_movie;
alter function public.test_update_collection_movie(uuid,text,text,smallint,smallint,text[],text,text,text,text,text,public.movie_watch_status,numeric,integer) rename to update_collection_movie;
alter function public.test_route_inbox_to_collection(uuid,public.collection_item_type,text,text,text,text,text,smallint,text[],numeric,integer) rename to route_inbox_to_collection;
alter function public.test_save_collection_item(uuid,public.collection_item_type,text,text,text,text,numeric,text,date,text,text,boolean,text,text) rename to save_collection_item;

drop function if exists public.test_route_inbox_to_collection(uuid,public.collection_item_type,text,text,text,text);

create or replace function public.create_collection_movie(p_title text,p_original_title text default null,p_release_year smallint default null,p_duration_minutes smallint default null,p_genres text[] default '{}',p_director text default null,p_image_url text default null,p_source_url text default null,p_note text default null,p_recommended_by text default null,p_status public.movie_watch_status default 'want_to_watch',p_external_rating numeric default null,p_kinopoisk_id integer default null) returns uuid language plpgsql set search_path=public as $$ declare v_item_id uuid; v_user_id uuid:=(select auth.uid()); begin if v_user_id is null then raise exception 'Authentication required'; end if; insert into public.collection_items(user_id,type,title,note,source_url,image_url) values(v_user_id,'movie',btrim(p_title),nullif(btrim(p_note),''),nullif(btrim(p_source_url),''),nullif(btrim(p_image_url),'')) returning id into v_item_id; insert into public.collection_movies(item_id,user_id,original_title,release_year,duration_minutes,genres,director,recommended_by,status,external_rating,kinopoisk_id) values(v_item_id,v_user_id,nullif(btrim(p_original_title),''),p_release_year,p_duration_minutes,coalesce(p_genres,'{}'),nullif(btrim(p_director),''),nullif(btrim(p_recommended_by),''),p_status,p_external_rating,p_kinopoisk_id); return v_item_id; end; $$;

create or replace function public.update_collection_movie(p_item_id uuid,p_title text,p_original_title text default null,p_release_year smallint default null,p_duration_minutes smallint default null,p_genres text[] default '{}',p_director text default null,p_image_url text default null,p_source_url text default null,p_note text default null,p_recommended_by text default null,p_status public.movie_watch_status default 'want_to_watch',p_external_rating numeric default null,p_kinopoisk_id integer default null) returns void language plpgsql set search_path=public as $$ begin update public.collection_items set title=btrim(p_title),note=nullif(btrim(p_note),''),source_url=nullif(btrim(p_source_url),''),image_url=nullif(btrim(p_image_url),'') where id=p_item_id and user_id=(select auth.uid()) and type='movie'; if not found then raise exception 'Movie not found'; end if; update public.collection_movies set original_title=nullif(btrim(p_original_title),''),release_year=p_release_year,duration_minutes=p_duration_minutes,genres=coalesce(p_genres,'{}'),director=nullif(btrim(p_director),''),recommended_by=nullif(btrim(p_recommended_by),''),status=p_status,external_rating=p_external_rating,kinopoisk_id=p_kinopoisk_id where item_id=p_item_id and user_id=(select auth.uid()); end; $$;

create or replace function public.route_inbox_to_collection(p_inbox_id uuid,p_type public.collection_item_type,p_title text,p_note text default null,p_source_url text default null,p_image_url text default null,p_original_title text default null,p_release_year smallint default null,p_genres text[] default '{}',p_external_rating numeric default null,p_kinopoisk_id integer default null) returns uuid language plpgsql set search_path=public as $$ declare v_item_id uuid; v_user_id uuid:=(select auth.uid()); begin if v_user_id is null then raise exception 'Authentication required'; end if; if not exists(select 1 from public.inbox_items where id=p_inbox_id and user_id=v_user_id and status='new') then raise exception 'Inbox item not found'; end if; insert into public.collection_items(user_id,type,title,note,source_url,image_url) values(v_user_id,p_type,btrim(p_title),nullif(btrim(p_note),''),nullif(btrim(p_source_url),''),nullif(btrim(p_image_url),'')) returning id into v_item_id; if p_type='movie' then insert into public.collection_movies(item_id,user_id,original_title,release_year,genres,external_rating,kinopoisk_id) values(v_item_id,v_user_id,nullif(btrim(p_original_title),''),p_release_year,coalesce(p_genres,'{}'),p_external_rating,p_kinopoisk_id); end if; insert into public.collection_inbox_links(inbox_id,item_id,user_id) values(p_inbox_id,v_item_id,v_user_id); return v_item_id; end; $$;

create or replace function public.save_collection_item(p_item_id uuid,p_type public.collection_item_type,p_title text,p_note text,p_source_url text,p_image_url text,p_price_amount numeric,p_currency text,p_birth_date date,p_location text,p_map_url text,p_visited boolean,p_content_kind text,p_content_status text) returns uuid language plpgsql set search_path=public as $$ declare v_item_id uuid:=p_item_id; v_user_id uuid:=(select auth.uid()); v_year integer; v_month integer; v_day integer; v_date date; begin if v_user_id is null then raise exception 'Authentication required'; end if; if v_item_id is null then insert into public.collection_items(user_id,type,title,note,source_url,image_url) values(v_user_id,p_type,btrim(p_title),nullif(btrim(p_note),''),nullif(btrim(p_source_url),''),nullif(btrim(p_image_url),'')) returning id into v_item_id; else update public.collection_items set title=btrim(p_title),note=nullif(btrim(p_note),''),source_url=nullif(btrim(p_source_url),''),image_url=nullif(btrim(p_image_url),'') where id=v_item_id and user_id=v_user_id and type=p_type; if not found then raise exception 'Collection item not found'; end if; end if; if p_type='purchase' then insert into public.collection_purchases(item_id,user_id,price_amount,currency) values(v_item_id,v_user_id,p_price_amount,coalesce(nullif(p_currency,''),'RUB')) on conflict(item_id) do update set price_amount=excluded.price_amount,currency=excluded.currency; elsif p_type='birthday' then insert into public.collection_birthdays(item_id,user_id,birth_date) values(v_item_id,v_user_id,p_birth_date) on conflict(item_id) do update set birth_date=excluded.birth_date; delete from public.collection_calendar_events where item_id=v_item_id and user_id=v_user_id; if p_birth_date is not null then v_month:=extract(month from p_birth_date); v_day:=extract(day from p_birth_date); for v_year in extract(year from current_date)::integer..extract(year from current_date)::integer+5 loop v_date:=make_date(v_year,v_month,least(v_day,extract(day from(make_date(v_year,v_month,1)+interval '1 month - 1 day'))::integer)); insert into public.collection_calendar_events(user_id,item_id,title,starts_at,ends_at,occurrence_year) values(v_user_id,v_item_id,'День рождения · '||btrim(p_title),(v_date+time '09:00') at time zone 'Europe/Moscow',(v_date+time '09:30') at time zone 'Europe/Moscow',v_year); end loop; end if; elsif p_type='place' then insert into public.collection_places(item_id,user_id,location,map_url,visited) values(v_item_id,v_user_id,nullif(btrim(p_location),''),nullif(btrim(p_map_url),''),coalesce(p_visited,false)) on conflict(item_id) do update set location=excluded.location,map_url=excluded.map_url,visited=excluded.visited; elsif p_type='learning' then insert into public.collection_learning(item_id,user_id,content_kind,status) values(v_item_id,v_user_id,coalesce(nullif(p_content_kind,''),'other'),coalesce(nullif(p_content_status,''),'saved')) on conflict(item_id) do update set content_kind=excluded.content_kind,status=excluded.status; end if; return v_item_id; end; $$;

revoke all on function public.create_collection_movie(text,text,smallint,smallint,text[],text,text,text,text,text,public.movie_watch_status,numeric,integer) from public;
grant execute on function public.create_collection_movie(text,text,smallint,smallint,text[],text,text,text,text,text,public.movie_watch_status,numeric,integer) to authenticated;
revoke all on function public.update_collection_movie(uuid,text,text,smallint,smallint,text[],text,text,text,text,text,public.movie_watch_status,numeric,integer) from public;
grant execute on function public.update_collection_movie(uuid,text,text,smallint,smallint,text[],text,text,text,text,text,public.movie_watch_status,numeric,integer) to authenticated;
revoke all on function public.route_inbox_to_collection(uuid,public.collection_item_type,text,text,text,text,text,smallint,text[],numeric,integer) from public;
grant execute on function public.route_inbox_to_collection(uuid,public.collection_item_type,text,text,text,text,text,smallint,text[],numeric,integer) to authenticated;
revoke all on function public.save_collection_item(uuid,public.collection_item_type,text,text,text,text,numeric,text,date,text,text,boolean,text,text) from public;
grant execute on function public.save_collection_item(uuid,public.collection_item_type,text,text,text,text,numeric,text,date,text,text,boolean,text,text) to authenticated;
